package test;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.entity.EntityDamageByEntityEvent;import org.bukkit.event.player.PlayerJoinEvent;import org.bukkit.plugin.java.JavaPlugin;import java.lang.reflect.*;import java.util.*;import net.minecraft.server.level.ServerPlayer;import dev.enco.greatcombat.GreatCombat;
public final class Probe extends JavaPlugin implements Listener {
 public void onEnable(){getServer().getPluginManager().registerEvents(this,this);}
 @EventHandler public void join(PlayerJoinEvent e){Player p=e.getPlayer();if(!p.getName().equals("TestOwner"))return;getServer().getScheduler().runTaskLater(this,()->{try{
 World w=p.getWorld();for(int x=-10;x<=10;x++)for(int z=-10;z<=10;z++){w.getBlockAt(x,99,z).setType(Material.STONE);for(int y=100;y<104;y++)w.getBlockAt(x,y,z).setType(Material.AIR);}p.teleport(new Location(w,.5,100,.5,0,0));
 JavaPlugin plugin=(JavaPlugin)getServer().getPluginManager().getPlugin("ElytrixBotsTrain");String path="players."+p.getUniqueId()+".";plugin.getConfig().set(path+"mode","crit");Method spawn=plugin.getClass().getDeclaredMethod("spawn",Player.class);spawn.setAccessible(true);spawn.invoke(plugin,p);Field f=plugin.getClass().getDeclaredField("bots");f.setAccessible(true);ServerPlayer b=(ServerPlayer)((Map<?,?>)f.get(plugin)).get(p.getUniqueId());Player fake=b.getBukkitEntity();var cm=GreatCombat.getInstance().getCombatManager();cm.startCombat(p,fake);getLogger().info("TAG OWNER TO BOT "+cm.isInCombat(p.getUniqueId()));cm.startCombat(fake,p);getLogger().info("TAG BOT TO OWNER "+cm.isInCombat(p.getUniqueId()));cm.startSingle(p);getLogger().info("TAG ACTIVE BEFORE "+cm.isInCombat(p.getUniqueId()));cm.startCombat(p,fake);getLogger().info("TAG ACTIVE AFTER "+cm.isInCombat(p.getUniqueId()));cm.stopCombat(cm.getUser(p.getUniqueId()));
 getServer().getScheduler().runTaskTimer(this,()->{if(plugin.getConfig().getString(path+"mode").equals("crit"))getLogger().info("STATE pos="+b.position()+" vel="+b.getDeltaMovement()+" ground="+b.onGround()+" fall="+b.fallDistance);},2L,5L);
 for(int i=0;i<4;i++){final String mode=new String[]{"crit","combo","pro","noob"}[i];long tick= i*100L;getServer().getScheduler().runTaskLater(this,()->{p.setHealth(p.getMaxHealth());p.teleport(new Location(w,.5,100,.5,0,0));fake.teleport(new Location(w,.5,100,2.5,180,0));plugin.getConfig().set(path+"mode",mode);getLogger().info("MODE START "+mode);},tick+1);}
 }catch(Throwable ex){getLogger().log(java.util.logging.Level.SEVERE,"PROBE FAIL",ex);}},30L);}
 @EventHandler(priority=EventPriority.MONITOR) public void damage(EntityDamageByEntityEvent e){if(e.getDamager().getName().startsWith("ElytrixBots_")){ServerPlayer b=((org.bukkit.craftbukkit.entity.CraftPlayer)e.getDamager()).getHandle();getLogger().info("BOT HIT "+e.getFinalDamage()+" cancelled="+e.isCancelled()+" fall="+b.fallDistance+" ground="+b.onGround()+" sprint="+b.isSprinting());}}
}
